"""Register corrected semantic cleft art without owning discovery or liquid background."""
from pathlib import Path
import json,hashlib
import numpy as np
from PIL import Image,ImageDraw,ImageFont
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];SRC=HERE/'blender-v4';OUT=SRC/'registered'
def read(p):return json.loads(p.read_text())
def ref(p):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8',newline='\n')
review=read(SRC/'independent-structural-review.json');assert review['recommendation']=='pass' and not review['fix_now']
for r in review['inputs']:assert ref(ROOT/r['path'])==r
audit=read(SRC/'reopen-audit.json');assert audit['reopened'] and not audit['external_render_images'] and all(not x[k]['zero_area_faces'] and not x[k]['nonmanifold_edges'] for x in audit['elements'] for k in ['base','evaluated'])
assert not (OUT/'model.json').exists();OUT.mkdir(exist_ok=True);a=np.array(Image.open(SRC/'refined-map-neutral.png').convert('RGBA'));a[:,:,:3]=np.uint8(np.round(a[:,:,:3].mean(2)))[:,:,None];a[a[:,:,3]==0,:3]=0;da=np.minimum(np.array(Image.open(SRC/'refined-map-detail.png'))[:,:,3],a[:,:,3]);w=np.uint8(np.round(np.divide(da.astype(float)*255,a[:,:,3],out=np.zeros_like(da,dtype=float),where=a[:,:,3]>0)));refs={}
for key,im in dict(primary=Image.fromarray(a),detail=Image.fromarray(a),coverage=Image.fromarray(a[:,:,3]),detail_coverage=Image.fromarray(da),detail_weight=Image.fromarray(w),authored_dualcolor_mask=Image.fromarray(np.dstack([w,w,w,a[:,:,3]]))).items():
 p=OUT/(key+'.png');im.save(p);refs[key]=ref(p)
source=read(HERE/'source-packet.json');controls=read(SRC/'model-controls.json');model=dict(kind='native_hidden_feature',blueprint='PondDown',native_tile=source['source_tile']['native_tile'],conditional_blueprint='PondDown',source=ref(HERE/'source-packet.json'),reference_correction=ref(SRC/'reference-correction.json'),blender_source=ref(SRC/'cleft.blend'),controls=ref(SRC/'model-controls.json'),**refs,registration=controls['registration'],native_states=source['native_states'],native_behavior=source['native_behavior'],visibility_policy='Read actual native Render.Visible each frame. Hidden must draw nothing; HiddenRender alone owns discovery/reveal and layer/name/foreground changes. Do not infer visibility from tile-name presence.',palette_policy='Native primary foreground and renderer-resolved detail/background. Default detail string empty and reveal does not overwrite it; never freeze illustrative k/blue values.',liquid_background='Native RenderLiquidBackground result must survive unchanged behind coverage; no water baked into art.',formula='coverage*luminance*((1-detail_weight)*native_primary+detail_weight*native_detail)+(1-coverage)*native_background',new_native_state_chooser=False,native_activation=False,native_acceptance='Pending full-set hidden/reveal/search/radar/liquid-background and stairs interaction review')
write(OUT/'model.json',model);pal=read(ROOT/'evidence/joppa-anatomy-study.json')['native_palette'];plate=Image.new('RGB',(1220,700),'#142823');d=ImageDraw.Draw(plate);font=ImageFont.truetype('C:/Windows/Fonts/consola.ttf',15);fg=np.array(list(bytes.fromhex(pal['Y'])));dt=np.array(list(bytes.fromhex(pal['k'])));t=a.copy();t[:,:,:3]=np.uint8(np.round(a[:,:,:3].astype(float)*((1-w[:,:,None]/255)*fg+w[:,:,None]/255*dt)/255));t[t[:,:,3]==0,:3]=0;Image.fromarray(t).save(OUT/'revealed-Y-k-illustration.png')
for i,(label,background,visible) in enumerate([('HIDDEN / NO ART','#'+pal['k'],False),('REVEALED / Y+k ILLUSTRATION','#'+pal['k'],True),('NATIVE LIQUID BACKGROUND PROOF','#285775',True)]):
 im=Image.fromarray(t) if visible else Image.new('RGBA',(512,768));bg=Image.new('RGBA',im.size,background);bg.alpha_composite(im);plate.paste(bg.convert('RGB').resize((256,384),Image.Resampling.LANCZOS),(35+i*405,65));d.text((20+i*405,20),label,font=font,fill='#e3cf43')
 for j,size in enumerate([(16,24),(24,36),(32,48)]):plate.paste(bg.convert('RGB').resize(size,Image.Resampling.LANCZOS),(45+i*405+j*85,485))
for i,line in enumerate(['Corrected continuous source cleft caps; same native16x24 map frame and semantic primary/detail roles.', 'k detail/blue liquid shown for illustration. Actual native visibility, detail and liquid result remain authoritative.', 'Default invisible; native search/radar reveals. No forced reveal, new stairs, terrain cut or baked background.', 'Registered artwork only. Whole-set game acceptance remains required.']):d.text((20,570+i*28),line,font=font,fill='#e5e8d8')
plate.save(OUT/'registration-comparison.png');print('Corrected cleft registered with native-owned reveal, semantic tint and liquid background.')
